<?php use App\Core\Authorization; ?>
<div class="page-heading"><div><p class="eyebrow">Insurance directory</p><h1>Non-teaching employees</h1><p>Maintain employee identities used by insurance policies.</p></div><div class="hero-actions insurance-heading-actions"><a class="button" href="<?=e(url('/insurance'))?>">Insurance policies</a><?php if(Authorization::allows('insurance.manage')):?><a class="button primary" href="<?=e(url('/insurance/employees/create'))?>">Add employee</a><?php endif;?></div></div><form class="filter-bar" method="get"><input name="q" value="<?=e($q)?>" placeholder="Employee number, name, or job title"><button class="button">Search</button></form><section class="card table-card"><table><thead><tr><th>Employee</th><th>Employee number</th><th>Job title</th><th>Department</th><th>Status</th><th>Policies</th><th></th></tr></thead><tbody><?php foreach($employees as $e):?><tr><td><strong><?=e($e['last_name'].', '.$e['first_name'])?></strong><br><small><?=e($e['email'])?></small></td><td><?=e($e['employee_no'])?></td><td><?=e($e['job_title']?:'—')?></td><td><?=e($e['department']?:'—')?></td><td><span class="badge"><?=e(str_replace('_',' ',$e['employment_status']))?></span></td><td><?=(int)$e['policy_count']?></td><td><?php if(Authorization::allows('insurance.manage')):?><a class="button small" href="<?=e(url('/insurance/employees/'.$e['id'].'/edit'))?>">Edit</a><?php endif;?></td></tr><?php endforeach;?><?php if(!$employees):?><tr><td colspan="7" class="empty">No non-teaching employees found.</td></tr><?php endif;?></tbody></table></section>
